};


/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.remove = async function () {
    /* sdd-asis-lifecycle:begin fn_Remove — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (await $c.win.confirm("삭제하시겠습니까?")) {
        (document.irDataForm || { elements: [] }).action = '/list/irData.do';
        $c.util.getComponent('dma_SearchReq').set('method', 'removeIRData');
        await scwin.tx_fn_Remove();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param resoroomId attachSeq attachFileChgDdtm attachFileNm
 * @returns
 * @hidden N
*/
scwin.fileDown = async function (resoroomId, attachSeq, attachFileChgDdtm, attachFileNm) {
    /* sdd-asis-lifecycle:begin fn_FileDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_SearchReq').set('resoroomId', resoroomId);
    $c.util.getComponent('dma_SearchReq').set('attachSeq', attachSeq);
    $c.util.getComponent('dma_SearchReq').set('attachFileChgDdtm', attachFileChgDdtm);
    $c.util.getComponent('dma_SearchReq').set('attachFileNm', attachFileNm);
    (document.fileDownForm || { elements: [] }).action = '/common/irDataFileDown.do';
    await scwin.tx_fn_FileDown();
    /* sdd-asis-lifecycle:end */
};
